#!/bin/bash
# Verdict records for the sections outside Tables A-C (judgement text here; counts read from raw/).
D=research/validation_sweep_20261019/A-leaderboard; RAW=$D/raw
rec() { # id table sources(json) recomputed_ok(json) replay_n replay_ok(json) rho(json) pricing(json) frozen(json) verdict notes
  jq -nc --arg id "$1" --arg t "$2" --argjson src "$3" --argjson rc "$4" --argjson rn "$5" --argjson rok "$6" --argjson rho "$7" --argjson pr "$8" --argjson fr "$9" --arg v "${10}" --arg notes "${11}" \
   '{row_id:$id,table:$t,source_paths:$src,recomputed_ok:$rc,replay_n:$rn,replay_ok:$rok,rho_reference_ok:$rho,pricing_ok:$pr,protocol_frozen_ok:$fr,verdict:$v,notes:$notes}'; }
ok_sessions() { grep -c "^$1.*VERIFIED" $RAW/replay_sessions.out; }
nat() { jq -r '"\([.replays[]|select(.reproduced)]|length)/\(.replays|length)"' "$RAW/replay_all/$1.receipt.json" 2>/dev/null || echo "not run"; }
R=research
rec "S:n37-bounded-K16" "n37" "[\"$R/ecbench_n37_rank_columns_20261004/RESULT.json\",\"$R/ecbench_n37_rank_columns_20261004/sessions/mac_arm64_l0_01/records.jsonl\",\"$R/ecbench_n37_rank_columns_20261004/PROTOCOL.md\"]" true 3 true '"partial"' false true validated_with_caveats \
 "Mean cold S of ic-k16 (2.1113), rho-strong (0.4194), K16/K42 (0.3490) and IC/rho (5.034) recompute exactly from the 40 verified measured records per arm. 3 seeded records verified by the independent verifier; the committed Linux audit (320/320 replays identical) is cited, not re-run. Freeze order is demonstrable: the session records git commit 5508af3 (2026-10-03 23:21) before the first raw commit (23:29). Pricing: the repository's own ecbench band marks every IC-vs-IC and IC-vs-rho pair 'unrankable (uncounted unpriced work)' (field_arithmetic, hash_and_allocation and modular_combination are named but not counted), so K16-over-K42 and IC/rho are lower-bound quotients that section 5a does not let anyone rank. The A/A control (ic-k42-control) is bit-identical because counts are deterministic, so it carries no noise information. Mac arm64 at L0. The board labels this a counted engineering lead, which is what the evidence supports."
rec "S:n37-K8-K16-confirmation" "n37" "[\"$R/ecbench_n37_k8_k16_20261004/DECISION.json\",\"$R/ecbench_n37_k8_k16_20261004/RAW-CALLGRIND.zip\",\"$R/ecbench_n37_k8_k16_20261004/PROTOCOL.md\"]" true 3 true '"partial"' false true validated_with_caveats \
 "K16/K8 Ir 1.1903 and K8/rho Ir 3.6446 recompute from the 16 per-workload Ir values in DECISION.json (sums of recorded values; the raw callgrind zip was not re-derived). 3 seeded ic-k8 records verified independently. The unit is simulated whole-solve instructions, so it is not wall time and not GAE; no 5a band applies to Ir. Session git commit f3a493f precedes data, but the analyzer was frozen after the data existed (commit 02:20 versus first raw 02:16)."
rec "S:n37-online-IR" "n37" "[\"$R/ecbench_n37_online_ir_20261004/DECISION.json\",\"$R/ecbench_n37_online_ir_20261004/PROTOCOL.md\"]" true 3 true '"partial"' false true validated_with_caveats \
 "K8/K16 online Ir 2.886 and K16/rho online Ir 0.1534 recompute from the per-workload parts. The 0.153 is target-only: K16's reusable pre-online Ir is about 38M against rho's 1.8M, so the same profiles give a complete-solve K16/rho of 4.70 (recomputed). The board states the interval as 'target-only', which is honest, but a reader of the 0.153 alone would miss that cold cost is 4.7 times rho's."
rec "S:n37-native-online-wall" "n37" "[\"$R/ecbench_n37_native_online_wall_20261004/DECISION.json\",\"$R/ecbench_n37_native_online_wall_20261004/EVIDENCE.json\"]" true 3 true '"partial"' '"not_applicable"' true validated_with_caveats \
 "rho/K16 online wall 7.178 on the primary workload recomputes as 4,107,367 ns over 572,221 ns (sum of recorded rounds). The decision file's own panel figure rho/K16 is 3.546 [2.03, 8.06] and K8/K16 7.110 [3.67, 16.98]; the board shows the primary-workload 7.178 and the K8/K16 panel but not the 3.546 panel ratio. All rows are L1 and the identical-K16 A/A deviation is 12.85 percent, above the 5 percent gate, so the board's 'no admitted speedup' is right and the 7.178 is descriptive only. Wall-clock, not an operation count; not a 5a quantity."
rec "S:n9-F6-IC-complete-small-solve" "n9" "[\"$R/f6_ic_geometric_closure_20261003/small_cold/measurements.jsonl\",\"$R/f6_ic_geometric_closure_20261003/small_cold/replay-certificate.json\",\"$R/f6_ic_geometric_closure_20261003/SMALL_COLD_PROTOCOL.md\"]" true 3 true '"not_applicable"' '"not_applicable"' false validated_with_caveats \
 "All three solver runs recovered the logarithm 4 of the public point (305, 466) in the order-37 subgroup of the GF(2^9) curve; [4]G = Q and [37]G = O verified independently (modulus x^9+x+1, a = 1, b = 1). The cold times 4.707 / 3.150 / 61.937 ms are single samples on an unverified-isolation Mac (L0), so the F4-versus-F6 ordering is one observation with no interval; the board gives no ratio, which is right. The subgroup has 37 elements (about 5 bits), so this is a correctness control, not evidence about scaling. Protocol and data land in one squashed PR commit (#1333), so freeze order is not demonstrable from git."
for m in 13 19 23; do
 case $m in 13) c=icv1-f2m13-t181-515ee569; rn=$(ok_sessions "f6ladder-m13");; 19) c=icv1-f2m19-t797-b6cf2467;; 23) c=icv1-f2m23-t5197-69e76b73;; esac
 nr=$(nat "f6_ic_ecbench_ladder_20261005__n$m")
 rec "S:F6-IC-ladder:m$m" "f6-ladder" "[\"$R/f6_ic_ecbench_ladder_20261005/ANALYSIS.json\",\"$R/f6_ic_ecbench_ladder_20261005/sessions/n$m/records.jsonl\",\"$R/f6_ic_ecbench_ladder_20261005/PROTOCOL.md\"]" true 6 false '"partial"' false false unvalidated \
  "Rho median S, F4/rho and F6/rho (median over 8 targets of the per-target mean paired ratio) recompute exactly from the 24 measured records per arm. 6 seeded IC records (3 ic-f4, 3 ic-f6) verify independently. BUT a replay-all of this session on this host with the main binary reproduces only $nr records (for m = 23 the replay-all had not finished when this audit closed, so that session is not covered): every ic-f4 and ic-f6 row differs in total_gae, phase counts or determinism (the committed 2026-10-05 audits passed on their binaries, so the drift arrived with later code or a different host class). The counters affected, solver word XORs, reductions and geometric additions, feed this row's W columns and the log2(W4/W6) column directly and its S lower bounds through the charged geometric additions. The band marks F4-vs-F6 'unresolved inside the band' and F4-versus-rho unresolved at m = 13, so the board's 'F6-IC saves solver work' is a statement about unpriced word XORs only. The squashed PR (#1358) holds protocol, adapter and results in one commit and the session records no git commit, so freeze order is not demonstrable. The decision is 'not decidable', which the board states."
done
for k in K13 R13 K19 R19; do
 nr=$(nat "f4_f5_f6_cross_family_20261011__$k")
 case $k in K13) c="koblitz m13";; R13) c="binary m13";; K19) c="koblitz m19";; R19) c="binary m19";; esac
 cov=true; rn=6
 case $k in R*) cov=false; rn=0;; esac
 if [ "$cov" = true ]; then
  rec "S:F4F5F6-cross-family:$k" "f4f5f6" "[\"$R/f4_f5_f6_cross_family_20261011/ANALYSIS.json\",\"$R/f4_f5_f6_cross_family_20261011/sessions/$k/records.jsonl\",\"$R/f4_f5_f6_cross_family_20261011/PROTOCOL.md\"]" true $rn false '"partial"' false false unvalidated \
   "The rho-negation, strong-rho, inherited-F4 and F6-IC S columns ($c) recompute exactly (median over targets of per-target mean S) from the verified measured records. 6 seeded records (3 inherited-f4, 3 f6-ic) verified by the independent verifier. Native replay-all on this host with the main binary reproduces only $nr records; every inherited-f4 and f6-ic row fails (and at K13 matrix-f4 and matrix-f5 too), although the 2026-10-11 committed audit reported all identical. The counters these rows publish therefore do not replay on current main. The band ranks rho below every IC arm and leaves F6-IC against F4 and the matrix engines 'unresolved inside the band'. The PR squash (#1674) merges protocol and results, and the recorded session commit is not in main, so freeze order is not demonstrable. Prime curves have no algebraic oracle here, as the board says."
 else
  rec "S:F4F5F6-cross-family:$k" "f4f5f6" "[\"$R/f4_f5_f6_cross_family_20261011/ANALYSIS.json\",\"$R/f4_f5_f6_cross_family_20261011/sessions/$k/records.jsonl\"]" true 0 false '"partial"' false false unvalidated \
   "S columns ($c) recompute exactly from the records. The independent scalar check is not covered: random binary curves are generated from a seed and the record carries no a, b coefficients, so the verifier could not be given the curve (not a pass). Native replay-all on this host with the main binary reproduces only $nr records (all inherited-f4 and f6-ic rows differ). Freeze order is not demonstrable (squashed PR #1674)."
 fi
done
rec "S:n41-f2m41" "n41-n53" "[\"$R/ecbench_n41_n53_shared_rank_20261005/DECISION.json\",\"$R/ecbench_n41_n53_shared_rank_20261005/sessions/mac-l0-02/records.jsonl\",\"$R/ecbench_n41_n53_shared_rank_20261005/PROTOCOL.md\"]" true 3 true '"partial"' false false validated_with_caveats \
 "rho-strong 0.157 (80/80 verified) and ic-k16 mean S 42.569 (23/80 verified, 57 exhausted) recompute exactly. 3 ic-k16 and 3 rho-strong records verified independently. The 42.569 and the 256x IC/rho quotient are means over the 23 runs that finished, so they carry survivor bias: 71 percent of ic-k16 runs and all ic-k8 runs (80 of 80 errors) produced no answer. The board does say that a cell that never verifies is unknown, and gives the verified counts. The band calls every IC-vs-rho pair 'incomplete'. L0 on a Mac. The n41/n53 protocol and data were merged in one squashed PR (#1512), so freeze order is not demonstrable (FREEZE.json names a source commit that is not in main)."
rec "S:n53-f2m53" "n41-n53" "[\"$R/ecbench_n41_n53_shared_rank_20261005/DECISION.json\",\"$R/ecbench_n41_n53_shared_rank_20261005/sessions/mac-l0-02/records.jsonl\"]" true 0 null '"partial"' false false validated_with_caveats \
 "rho-strong 0.141 (80/80) recomputes exactly; all 240 IC runs at this size ended in status error, so there is no IC scalar to replay (the seeded draw for this row returned records from the n41 curve, which is why it is excluded from this row's replay count). The board correctly reports 'unknown (0 verified pairs)'. Nothing here supports an IC cost at n = 53."
rec "S:conductor-gap:ell8209" "conductor-gap" "[\"$R/ecbench_conductor_gap_20261012/analysis.json\",\"$R/ecbench_conductor_gap_20261012/sessions/ell8209-q29/records.jsonl\",\"$R/ecbench_conductor_gap_20261012/PROTOCOL.md\"]" true 3 true true false true validated_with_caveats \
 "Floor/crater IC S ratio 0.9752 recomputes from the means over 8 verified targets per curve (19.870 / 20.374). 3 seeded ic-mitm records verified independently on the prime curve (p = 320092037). The comparison is two fixed curves, 8 targets each, so it says nothing about the class; the board says so. The same session has IC/rho at about 20 (not shown on the board), and the band ranks rho below IC at every weight, so the board's omission does not change an ordering. The rho A/A arm is bit-identical (counts), so it measures no noise. Protocol precedes data in git."
rec "S:conductor-gap:ell131101" "conductor-gap" "[\"$R/ecbench_conductor_gap_20261012/analysis.json\",\"$R/ecbench_conductor_gap_20261012/sessions/ell131101-q37/records.jsonl\"]" true 3 true true false true validated_with_caveats \
 "Floor/crater ratio 1.1271 recomputes (49.734 / 44.124 with orientation as published). 3 seeded records verified independently. Same limits as ell 8209: two fixed curves, 8 targets each, deterministic A/A; the 99 percent interval [0.922, 1.342] contains 1."
rec "S:N83-tier1-cold-holdout" "n83" "[\"$R/n83_e2e_holdout_20261016/ic1_rows_38955665283.json\",\"$R/n83_e2e_holdout_20261016/answers.jsonl\",\"$R/n83_e2e_holdout_20261016/PROTOCOL.md\"]" true 5 true '"partial"' '"not_applicable"' true validated_with_caveats \
 "Mean cold seconds per K (120.227, 121.296, 119.826, 122.471) and rho online (2.164 s) recompute exactly from the 25 IC rows; cold IC/rho online 55.55 = 120.227/2.164. All 5 sealed public points verify independently ([d]G = Q and [r]G = O on GF(2^83), a = 1, b = 1). The IC recovered scalars themselves are checked by the run's correctness receipts, which were not re-run (GitHub-hosted Linux run 38955665283). The ratio divides a cold IC process by rho's online interval only, which is not a matched cold ratio, as the board says; the selected candidate is null. Freeze order is demonstrable: protocol, answers and targets were committed at 10:17 'before grid result', selection sealed 11:55, results 14:21 on 2026-10-16."
rec "S:frontier:rho-optimized-callgrind" "frontier" "[\"$R/ecbench_rho_optimized_20261014/RESULT.json\",\"$R/ecbench_rho_optimized_20261014/callgrind/\"]" true 3 true '"not_applicable"' '"not_applicable"' true validated "Solve Ir 1,989,285,300 (archived), 1,995,304,985 (same-binary legacy) and 1,600,543,701 (optimized) re-derive from the raw callgrind files with ecbench callgrind-ir; the ratios 0.80458 and 0.80215 recompute. The board calls it an engineering improvement to rho with no change to ranked rows, which matches the data. Consequence for this audit: Tables A and C price rho before this improvement, so their x reference is measured against a rho about 1.25 times slower in instructions than the current standing one (an effect on the reference, not on any IC figure)."
rec "S:frontier:cold-bound-1.089" "frontier" "[\"docs/bounds/records/pair-claw-koblitz-rho-strong.json\",\"docs/bounds/frontier.json\"]" true 0 null '"not_applicable"' '"partial"' null validated_with_caveats "ecbench bound check re-derives the committed bounds (exit 0, empty output). The 1.089x floor figure was not re-derived by name; it is rho's own boundary, not an IC row. Not covered: a seeded replay of the 144 runs."
rec "S:frontier:n61-compact-orbit-online" "frontier" "[\"docs/ic/BOUNDARY_TARGETS.md\",\"research/ecbench_frontier_20261013/frontier-data.json\"]" null 0 null '"partial"' '"not_applicable"' null unvalidated "The board quotes rho/IC 13.9 [9.8, 19.1] over 64 targets with about 28 s of setup excluded (cold IC/rho 83.4). The figure is taken from a BOUNDARY_TARGETS.md table cell and frontier-data.json; the underlying 2026-10-12 sessions are not among the board's listed sources and were not located in this audit, so nothing could be recomputed or replayed. The text itself says the 28 s setup is excluded and that this is a constant-factor result; the retained-setup ratio is correctly kept apart from cold rows. Not covered: locate the sessions and run ecbench claim."
rec "S:frontier:n83-dense-K1798-online" "frontier" "[\"research/ecbench_frontier_20261013/frontier-data.json\",\"research/n83_dense_root_20261013/REPORT.md\"]" true 0 null '"not_applicable"' '"not_applicable"' null validated_with_caveats "The arithmetic recomputes from the recorded seconds: rho online 1.17329 s over IC online 0.063324 s = 18.528; complete process 339.068 s over rho online = 288.99; break-even 305.4 targets. It is one point on a shared host and the cold ratio is not matched (rho setup not reported), which the board states. No replay covered."
nr=$(nat "ecbench_rootfind_engine_20261012__claim-n13")
rec "S:frontier:rootfinder-replay-block" "frontier" "[\"research/ecbench_frontier_20261013/README.md\",\"research/ecbench_frontier_20261013/audits/rootfind-n13-replay-all-failed.json\",\"research/ecbench_rootfind_engine_20261012/sessions/claim-n13\"]" true 0 false '"not_applicable"' '"not_applicable"' null contradicted "The board says 120/168 identical with 48 inherited-F4 counter mismatches. The committed failed receipt does say 120/168. Replaying the same session now, on this host with the main binary, gives $nr identical, and the failures are not confined to inherited F4: all four IC arms differ (ic-f4-m2, ic-f4-m3, ic-rootfind-m2, ic-rootfind-m3, 24 rows each), so the published statement that 'all root-finder and rho rows pass' no longer holds on current main. See the report for the rows these counters feed."
for c in 16384 65536 131072 262144; do
 rec "J:linear-algebra-engines:$c-columns" "la-engines" "[\"$R/la_engines_20261014/summary.json\",\"$R/la_engines_20261014/raw/grid_amend5.jsonl\",\"$R/la_engines_20261014/PROTOCOL_AMENDMENT_5.md\"]" true 0 null '"not_applicable"' '"not_applicable"' '"partial"' validated_with_caveats \
  "Median solve seconds for legacy-bw, cado-bw (the board's cado_style) and cado-nfs at $c columns recompute exactly from grid_amend5.jsonl (3 runs per arm). This row appears only in leaderboard.json, not in LEADERBOARD.md. It is a linear-algebra component time, an engineering figure, not an end-to-end S and with no rho reference. n = 3 per cell. Not covered: a replay of the solvers. The cado-nfs column is a whole external pipeline with a fixed cost near 3.3 s even at 1,024 columns, so cado_nfs_over_ours of 20x at 16,384 columns is a startup effect, not a throughput ratio (it falls to 1.9x at 262,144 columns). Protocol: five amendments, each declared before its own grid but after earlier grids were seen, so the sequence of experiments was adaptive."
done
rec "J:oracle-pricing-cells(9)" "oracles" "[\"docs/ic/runs/ic-oracle-pricing-lifted-2026-09-21.json\"]" true 0 null '"not_applicable"' '"not_applicable"' '"partial"' validated_with_caveats \
 "The nine cells (n = 9 to 19, m = 2 or 3) carry per-oracle mean GAE per target; each recomputes exactly as the mean of its per-target gae values, no cell has a disagreement between oracles, and cell 7 reports 8 inconclusive targets, which the board keeps. These are oracle costs on Koblitz Semaev systems, not ratios to rho. Not covered: replay of the oracle runs, and the band (matrix F4 is priced with a pinned word-XOR ratio that was not recomputed)."
